// 전체 실적 테이블용 데이터 변환
const allMonthsTableData = {};
Object.keys(dashboardData.months).forEach(month => {
    allMonthsTableData[month] = [];
    dashboardData.months[month].agencies.forEach(ag => {
        allMonthsTableData[month].push({
            "대리점명": ag.name,
            "팀명": ag.manager,
            "무선목표": ag.summary.wirelessDetails.target,
            "무선실적": ag.summary.wirelessDetails.current,
            "무선달성률": ag.summary.wirelessRate / 100,
            "유선목표": ag.summary.wiredDetails.target,
            "유선실적": ag.summary.wiredDetails.current,
            "유선달성률": ag.summary.wiredRate / 100,
            "소매ARPU목표": ag.summary.retailDetails ? ag.summary.retailDetails.target : 80186,
            "소매ARPU실적": ag.summary.retailDetails ? ag.summary.retailDetails.current : 80186,
            "소매ARPU달성률": ag.summary.retailArpuRate / 100,
            "ARPU달성그룹": ag.summary.retailArpuRate >= 100 ? "1" : "2",
            "유심목표": ag.summary.mnpDetails ? ag.summary.mnpDetails.target : 0,
            "유심달성률": ag.summary.usimMnpRate / 100,
            "유심실적가점": ag.summary.mnpDetails ? ag.summary.mnpDetails.current : 0,
            "초고속달성률": ag.summary.wiredRate / 100,
            "공통지원금등록률": ag.targetStatus.bonusUsageRate / 100,
            "달성여부": ag.summary.totalAmount > 0 ? "달성" : "미달성",
            "최종지급테이블": ag.targetStatus.finalTable || (ag.summary.totalAmount > 10000000 ? "1그룹" : (ag.summary.totalAmount > 0 ? "2그룹" : "3그룹")),
            "수혜금액": ag.summary.totalAmount,
            "TACplus": 1,
            "고가기변": ag.summary.benefitHighUpgrade,
            "고가MNP": ag.summary.benefitHighMnp,
            "유심중고": ag.summary.benefitGal26
        });
    });
});

if (typeof module !== 'undefined') module.exports = dashboardData;
